    String pdfExtension = mActivity.getString(R.string.pdf_ext);
    String encryptedSuffix = mActivity.getString(R.string.encrypted_file);

    String outputPath = path.endsWith(pdfExtension)
            ? path.substring(0, path.length() - pdfExtension.length()) + encryptedSuffix
            : path + encryptedSuffix;

    return FileUtils.getUniqueFileName(outputPath);
